```yaml
rules:
  - id: no-hardcoded-secrets-go
    languages: [go]
    severity: ERROR
    message: Hardcoded credential found in source; load secrets from environment variables or a secret manager instead.
    metadata:
      category: security
    patterns:
      - pattern-either:
          - pattern: $X := $V
          - pattern: var $X = $V
          - pattern: $X = $V
          - pattern: $K: $V
          - pattern: return $V
          - pattern: $F(..., $V, ...)
      - metavariable-regex:
          metavariable: $V
          regex: '^["`][^"`]*(AKIA[0-9A-Z]{16}|gh[pousr]_[A-Za-z0-9]{36}|xox[abprs]-[A-Za-z0-9-]{10,}|sk_live_[0-9A-Za-z]{16,}|-----BEGIN [A-Z ]*PRIVATE KEY|[a-zA-Z][a-zA-Z0-9+.-]*://[^\s:/@"`]+:[^\s@/"`]+@|Bearer [A-Za-z0-9._~+/=-]{16,})'
```

```go
package main

import (
	"fmt"
	"os"
)

type Config struct {
	Token string
}

// ruleid: no-hardcoded-secrets-go
var awsKey = "AKIAABCDEFGHIJKLMNOP"

// ruleid: no-hardcoded-secrets-go
var dbURL = "postgres://app:S3cr3tPass@db.internal:5432/app"

// ok: no-hardcoded-secrets-go
var greeting = "hello world"

// ok: no-hardcoded-secrets-go
var placeholder = "<API_KEY>"

// ok: no-hardcoded-secrets-go
var localDSN = "postgres://localhost:5432/app"

func privateKey() string {
	// ruleid: no-hardcoded-secrets-go
	return "-----BEGIN RSA PRIVATE KEY-----"
}

func main() {
	// ok: no-hardcoded-secrets-go
	token := os.Getenv("API_TOKEN")
	// ruleid: no-hardcoded-secrets-go
	cfg := Config{Token: "ghp_abcdefghijklmnopqrstuvwxyz0123456789"}
	fmt.Println(token, cfg.Token, privateKey(), dbURL, awsKey, greeting, placeholder, localDSN)
}
```

